using System.Text.RegularExpressions;

void Teste(string t, string m) =>
    Console.WriteLine(
        $"{m} in {t}: {Regex.IsMatch(t, m)}");

Teste("Ich bin in der HTL", "HTL");
Teste("Ich bin in der htl", "HTL");
Teste("Raum B3", @"[A-Z]\d");
Teste("3x5", @"3.5");
Teste("3x5", @"3\.5");
// Ausgabe:
// HTL in Ich bin in der HTL: True
// HTL in Ich bin in der htl: False
// [A-Z]\d in Raum B3: True
// 3.5 in 3x5: True
// 3\.5 in 3x5: False

Teste("Hallooo", "Hallo+");
Teste("Hall", "Hallo+");
Teste("color", "colou?r");
Teste("A1", @"\d{2}");
Teste("8020 Graz", @"\d{4}");
// Ausgabe:
// Hallo+ in Hallooo: True
// Hallo+ in Hall: False
// colou?r in color: True
// \d{2} in A1: False
// \d{4} in 8020 Graz: True

Teste("12345", @"\d{4}");
Teste("12345", @"^\d{4}$");
Teste("8020", @"^\d{4}$");
Teste("Katzenfutter", @"\bKatze\b");
Teste("die Katze", @"\bKatze\b");
// Ausgabe:
// \d{4} in 12345: True
// ^\d{4}$ in 12345: False
// ^\d{4}$ in 8020: True
// \bKatze\b in Katzenfutter: False
// \bKatze\b in die Katze: True

Teste("hahaha", "^(ha)+$");
Teste("haa", "^(ha)+$");
Teste("Di", "^(Mo|Di|Mi|Do|Fr)$");
Teste("Sa", "^(Mo|Di|Mi|Do|Fr)$");
Teste("Montag", "^Mo|Fr$");
// Ausgabe:
// ^(ha)+$ in hahaha: True
// ^(ha)+$ in haa: False
// ^(Mo|Di|Mi|Do|Fr)$ in Di: True
// ^(Mo|Di|Mi|Do|Fr)$ in Sa: False
// ^Mo|Fr$ in Montag: True

